def getHappyString(n, k):
    if k > 3 * 2 ** (n - 1):
        return ''
    result = []
    chars = ['a', 'b', 'c']
    for i in range(n):
        base = 2 ** (n - i - 1)
        idx = (k - 1) // base
        c = chars[idx]
        while result and result[-1] == c:
            c = chars[(chars.index(c) + 1) % 3]
        result.append(c)
        k -= idx * base
    return ''.join(result)
